fn quantize_value(value: f32, quant_min: f32, quant_scale: f32) -> u8 {
    if quant_scale <= 0.0 {
        return 0;
    }

    ((value - quant_min) * quant_scale)
        .round()
        .clamp(0.0, 255.0) as u8
}

