impl QuantizedQuery {
    fn new(query: &[f32], quant_min: f32, quant_scale: f32) -> Self {
        let mut values = [0u8; DIM];

        for dim in 0..DIM {
            values[dim] = quantize_value(query[dim], quant_min, quant_scale);
        }

        Self { values }
    }
}

